// PG_TABLE_ATTR: placement of the constant DSP lookup tables (lead wavetables, bass sine and
// BLEP tables). They are `const` data generated by tools/gen/gen_tables.cpp,
// so by default they live in .rodata: on the ESP32-S3 that is flash, mapped
// through the flash cache, and costs no internal RAM.
//
// If profiling on the device shows flash-cache misses in the oscillators, the
// firmware can move the hot tables into internal RAM without touching this
// code, e.g. with -DPG_TABLE_ATTR=DRAM_ATTR (ESP-IDF, ~26 KB of DRAM for all
// of them). On the host it is empty.
#pragma once

#ifndef PG_TABLE_ATTR
#define PG_TABLE_ATTR
#endif
